import React, { useState } from 'react';

// ─── Brand tokens ─────────────────────────────────────────────────────────────
const BLUE   = '#009FE3';
const NAVY   = '#003D6B';
const YELLOW = '#FFD100';

// ─── Types ───────────────────────────────────────────────────────────────────

export interface ParameterDef {
  id: string;
  label: string;
  /** Must match the ThoughtSpot parameter name exactly (case-sensitive) */
  parameterName: string;
  options: { label: string; value: string }[];
  defaultValue: string;
  /**
   * Expandable data shown below the option list when the card is open.
   * - valueMap: dimension picker — maps each option value to its underlying data values
   * - descriptionMap: metric picker — maps each option value to a plain-English description
   */
  expandable?: {
    valueMap?: Record<string, string[]>;
    descriptionMap?: Record<string, { description: string; formula?: string }>;
  };
}

export type ParameterSelection = Record<string, string>;

interface ParameterBarProps {
  parameters: ParameterDef[];
  selected: ParameterSelection;
  onSelectionChange: (parameterId: string, value: string) => void;
  onResetAll: () => void;
}

// ─── Chevron icon ─────────────────────────────────────────────────────────────

function Chevron({ open }: { open: boolean }) {
  return (
    <svg
      width="12"
      height="12"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{
        transform: open ? 'rotate(180deg)' : 'rotate(0deg)',
        transition: 'transform 0.2s ease',
        flexShrink: 0,
      }}
    >
      <polyline points="6 9 12 15 18 9" />
    </svg>
  );
}

// ─── Expanded panel — dimension values ────────────────────────────────────────

function DimensionValuePanel({
  dimensionLabel,
  values,
}: {
  dimensionLabel: string;
  values: string[];
}) {
  if (!values.length) {
    return (
      <div style={{ padding: '10px 12px', fontSize: 12, color: 'rgba(0,0,0,0.40)', fontStyle: 'italic' }}>
        No values configured for this dimension.
      </div>
    );
  }

  return (
    <div style={{ padding: '10px 12px 12px' }}>
      <div
        style={{
          fontSize: 10,
          fontWeight: 700,
          letterSpacing: '0.08em',
          textTransform: 'uppercase',
          color: BLUE,
          marginBottom: 8,
        }}
      >
        {dimensionLabel} values
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5 }}>
        {values.map((v) => (
          <span
            key={v}
            style={{
              fontSize: 11,
              fontWeight: 500,
              color: NAVY,
              backgroundColor: 'rgba(0,159,227,0.08)',
              border: '1px solid rgba(0,159,227,0.18)',
              borderRadius: 5,
              padding: '3px 8px',
              whiteSpace: 'nowrap',
              letterSpacing: '-0.01em',
            }}
          >
            {v}
          </span>
        ))}
      </div>
    </div>
  );
}

// ─── Expanded panel — metric description ──────────────────────────────────────

function MetricDescriptionPanel({
  metricLabel,
  description,
  formula,
}: {
  metricLabel: string;
  description: string;
  formula?: string;
}) {
  return (
    <div style={{ padding: '10px 12px 12px' }}>
      <div
        style={{
          fontSize: 10,
          fontWeight: 700,
          letterSpacing: '0.08em',
          textTransform: 'uppercase',
          color: '#8B6914',
          marginBottom: 6,
        }}
      >
        {metricLabel}
      </div>
      <p
        style={{
          fontSize: 12,
          color: '#444',
          lineHeight: 1.55,
          margin: '0 0 8px',
        }}
      >
        {description}
      </p>
      {formula && (
        <div
          style={{
            fontSize: 11,
            fontFamily: 'monospace',
            color: NAVY,
            backgroundColor: 'rgba(0,61,107,0.06)',
            border: '1px solid rgba(0,61,107,0.12)',
            borderRadius: 5,
            padding: '5px 8px',
            wordBreak: 'break-word' as const,
          }}
        >
          {formula}
        </div>
      )}
    </div>
  );
}

// ─── Single parameter card ────────────────────────────────────────────────────

function ParameterCard({
  param,
  selected,
  onChange,
}: {
  param: ParameterDef;
  selected: string;
  onChange: (value: string) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const isDefault    = selected === param.defaultValue;
  const isExpandable = !!param.expandable;

  // Resolve what to show in the expanded panel
  const expandedValues =
    param.expandable?.valueMap?.[selected] ?? [];
  const expandedMeta =
    param.expandable?.descriptionMap?.[selected];

  return (
    <div
      style={{
        width: 230,
        flexShrink: 0,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#FFFFFF',
        borderRadius: 10,
        border: `1.5px solid ${!isDefault ? YELLOW : expanded ? 'rgba(0,0,0,0.18)' : 'rgba(0,0,0,0.09)'}`,
        boxShadow: !isDefault
          ? `0 0 0 3px rgba(255,209,0,0.18), 0 2px 8px rgba(0,0,0,0.06)`
          : expanded
            ? '0 4px 16px rgba(0,0,0,0.10)'
            : '0 1px 4px rgba(0,0,0,0.06)',
        overflow: 'hidden',
        transition: 'border-color 0.15s ease, box-shadow 0.15s ease',
      }}
    >
      {/* ── Card header ── */}
      <div
        style={{
          padding: '9px 12px 8px',
          borderBottom: '1px solid rgba(0,0,0,0.07)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexShrink: 0,
          background: !isDefault
            ? `linear-gradient(135deg, rgba(255,209,0,0.12) 0%, rgba(255,209,0,0.04) 100%)`
            : '#FAFAFA',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <svg
            width="11" height="11" viewBox="0 0 24 24" fill="none"
            stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'}
            strokeWidth="2.5" strokeLinecap="round"
          >
            <line x1="4" y1="6" x2="20" y2="6" />
            <line x1="4" y1="12" x2="20" y2="12" />
            <line x1="4" y1="18" x2="20" y2="18" />
            <circle cx="9"  cy="6"  r="2" fill={!isDefault ? YELLOW : '#FFF'} stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'} strokeWidth="2" />
            <circle cx="15" cy="12" r="2" fill={!isDefault ? YELLOW : '#FFF'} stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'} strokeWidth="2" />
            <circle cx="9"  cy="18" r="2" fill={!isDefault ? YELLOW : '#FFF'} stroke={!isDefault ? '#B8860B' : 'rgba(0,0,0,0.35)'} strokeWidth="2" />
          </svg>
          <span style={{ fontSize: 12, fontWeight: 700, color: !isDefault ? '#8B6914' : NAVY, letterSpacing: '-0.01em' }}>
            {param.label}
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
          {/* Selected value badge */}
          <span
            style={{
              fontSize: 10, fontWeight: 700,
              color: !isDefault ? '#8B6914' : 'rgba(0,0,0,0.35)',
              backgroundColor: !isDefault ? YELLOW : 'rgba(0,0,0,0.06)',
              borderRadius: 5, padding: '2px 7px',
              maxWidth: 80, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
            }}
          >
            {param.options.find((o) => o.value === selected)?.label ?? selected}
          </span>

          {/* Per-card reset */}
          {!isDefault && (
            <button
              type="button"
              onClick={() => onChange(param.defaultValue)}
              title={`Reset to default (${param.defaultValue})`}
              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '1px 3px', color: 'rgba(0,0,0,0.35)', display: 'flex', alignItems: 'center' }}
            >
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
                <path d="M3 3v5h5" />
              </svg>
            </button>
          )}

          {/* Expand toggle */}
          {isExpandable && (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              title={expanded ? 'Collapse' : 'Expand to see underlying data'}
              style={{
                background: 'none', border: 'none', cursor: 'pointer',
                padding: '1px 3px', display: 'flex', alignItems: 'center',
                color: expanded ? BLUE : 'rgba(0,0,0,0.35)',
              }}
            >
              <Chevron open={expanded} />
            </button>
          )}
        </div>
      </div>

      {/* ── Scrollable single-select option list ── */}
      <div
        style={{
          overflowY: 'auto',
          maxHeight: 172,
          padding: '3px 0',
          scrollbarWidth: 'thin',
          scrollbarColor: `rgba(255,209,0,0.4) transparent`,
        }}
      >
        {param.options.map((option) => {
          const isSelected = selected === option.value;
          return (
            <label
              key={option.value}
              style={{
                display: 'flex', alignItems: 'center', gap: 8,
                padding: '6px 12px', cursor: 'pointer',
                backgroundColor: isSelected ? 'rgba(255,209,0,0.12)' : 'transparent',
                transition: 'background-color 0.10s ease', userSelect: 'none',
              }}
              onMouseEnter={(e) => { if (!isSelected) (e.currentTarget as HTMLElement).style.backgroundColor = 'rgba(0,0,0,0.03)'; }}
              onMouseLeave={(e) => { (e.currentTarget as HTMLElement).style.backgroundColor = isSelected ? 'rgba(255,209,0,0.12)' : 'transparent'; }}
            >
              {/* Radio circle */}
              <span
                style={{
                  width: 15, height: 15, borderRadius: '50%', flexShrink: 0,
                  border: `2px solid ${isSelected ? BLUE : 'rgba(0,0,0,0.22)'}`,
                  backgroundColor: '#FFFFFF', display: 'flex', alignItems: 'center', justifyContent: 'center',
                  transition: 'all 0.10s ease',
                }}
              >
                {isSelected && <span style={{ width: 7, height: 7, borderRadius: '50%', backgroundColor: BLUE }} />}
              </span>
              <input type="radio" name={param.id} value={option.value} checked={isSelected} onChange={() => onChange(option.value)} style={{ display: 'none' }} />
              <span style={{ fontSize: 12.5, color: isSelected ? NAVY : '#2a2a2a', fontWeight: isSelected ? 700 : 400, letterSpacing: '-0.01em', lineHeight: 1.3, flex: 1, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {option.label}
              </span>
              {isSelected && (
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="20 6 9 17 4 12" />
                </svg>
              )}
            </label>
          );
        })}
      </div>

      {/* ── Expandable data panel ── */}
      {expanded && (
        <div style={{ borderTop: '1px solid rgba(0,0,0,0.07)' }}>
          {expandedValues.length > 0 && (
            <DimensionValuePanel
              dimensionLabel={param.options.find((o) => o.value === selected)?.label ?? selected}
              values={expandedValues}
            />
          )}
          {expandedMeta && (
            <MetricDescriptionPanel
              metricLabel={param.options.find((o) => o.value === selected)?.label ?? selected}
              description={expandedMeta.description}
              formula={expandedMeta.formula}
            />
          )}
          {!expandedValues.length && !expandedMeta && (
            <div style={{ padding: '10px 12px', fontSize: 12, color: 'rgba(0,0,0,0.40)', fontStyle: 'italic' }}>
              No additional data available for this selection.
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ─── Parameter bar ────────────────────────────────────────────────────────────

export default function ParameterBar({
  parameters,
  selected,
  onSelectionChange,
  onResetAll,
}: ParameterBarProps) {
  const hasNonDefault = parameters.some(
    (p) => (selected[p.id] ?? p.defaultValue) !== p.defaultValue
  );

  return (
    <div style={{ padding: '0 2.5rem 1rem' }}>
      {/* ── Bar header ── */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke={NAVY} strokeWidth="2.2" strokeLinecap="round">
            <line x1="4" y1="6" x2="20" y2="6" />
            <line x1="4" y1="12" x2="20" y2="12" />
            <line x1="4" y1="18" x2="20" y2="18" />
            <circle cx="9"  cy="6"  r="2.5" fill="white" stroke={NAVY} strokeWidth="2" />
            <circle cx="15" cy="12" r="2.5" fill="white" stroke={NAVY} strokeWidth="2" />
            <circle cx="9"  cy="18" r="2.5" fill="white" stroke={NAVY} strokeWidth="2" />
          </svg>
          <span style={{ fontSize: 12, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>Parameters</span>
          {hasNonDefault ? (
            <span style={{ fontSize: 10, fontWeight: 700, backgroundColor: YELLOW, color: '#7A5C00', borderRadius: 10, padding: '1px 7px', letterSpacing: '0.02em' }}>
              modified
            </span>
          ) : (
            <span style={{ fontSize: 10, fontWeight: 500, color: 'rgba(0,0,0,0.35)', letterSpacing: '0.01em' }}>
              · changes what the dashboard calculates · ∨ expand a card to see underlying values
            </span>
          )}
        </div>

        {hasNonDefault && (
          <button
            type="button" onClick={onResetAll}
            style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 12, color: 'rgba(0,0,0,0.40)', fontWeight: 500, padding: 0, letterSpacing: '-0.01em', display: 'flex', alignItems: 'center', gap: 5 }}
          >
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
              <path d="M3 3v5h5" />
            </svg>
            Reset to defaults
          </button>
        )}
      </div>

      {/* ── Horizontally scrollable card row ── */}
      <div style={{ display: 'flex', gap: 10, overflowX: 'auto', paddingBottom: 4, scrollbarWidth: 'thin', scrollbarColor: `rgba(255,209,0,0.35) transparent` }}>
        {parameters.map((p) => (
          <ParameterCard
            key={p.id}
            param={p}
            selected={selected[p.id] ?? p.defaultValue}
            onChange={(value) => onSelectionChange(p.id, value)}
          />
        ))}
      </div>
    </div>
  );
}
